def make_pool_peak_hook():
    '''Independent CuPy MemoryHook: rounded live pool bytes incl. temporaries; None without CuPy.'''
    cp = sm.cp
    if cp is None:
        return None

    class PoolPeakHook(cp.cuda.MemoryHook):
        name = 'daily_water_growth_pool_peak'

        def __init__(self):
            super().__init__()
            self.live_bytes, self.peak_bytes, self.n_malloc, self._sizes = 0, 0, 0, {}

        def malloc_postprocess(self, **kwargs):
            size = int(kwargs.get('mem_size', 0))
            self._sizes[kwargs.get('mem_ptr')] = size
            self.live_bytes += size
            self.n_malloc += 1
            self.peak_bytes = max(self.peak_bytes, self.live_bytes)

        def free_postprocess(self, **kwargs):
            self.live_bytes -= self._sizes.pop(kwargs.get('mem_ptr'), int(kwargs.get('mem_size', 0)))

        def report(self):
            return {'peak_bytes': self.peak_bytes, 'live_bytes': self.live_bytes, 'n_malloc': self.n_malloc,
                    'note': 'rounded pool chunks incl. temporaries; excludes CUDA context'}

    return PoolPeakHook()
